const overlay=document.getElementById('overlay');
const mini=document.getElementById('miniPlayer');
const started=document.getElementById('getStarted');
const close=document.getElementById('closePlayer');
const pause=document.getElementById('pauseBtn');
const topPlay=document.getElementById('topPlay');
let playing=true, seconds=11;
function openPlayer(){overlay.classList.add('open')}
mini.addEventListener('click',openPlayer);
started.addEventListener('click',openPlayer);
close.addEventListener('click',()=>overlay.classList.remove('open'));
function toggle(){
 playing=!playing;
 pause.textContent=playing?'Ⅱ':'▶';
 topPlay.textContent=playing?'Ⅱ':'▶';
}
pause.addEventListener('click',toggle);
topPlay.addEventListener('click',toggle);
setInterval(()=>{
 if(playing && overlay.classList.contains('open')){
   seconds++;
   const m=Math.floor(seconds/60),s=String(seconds%60).padStart(2,'0');
   document.getElementById('elapsed').textContent=m+':'+s;
 }
},1000);
